284	/**
285	 * The people kept on a sheet, in the order they were added. A name is stored without surrounding
286	 * spaces and is unique on its sheet regardless of case. An edit is made from a version of the
287	 * person; once someone else has saved the person since, it is refused.
288	 */
289	@Service
290	public class PersonService {
291	
292	    private static final int MAX_NAME = 100;
293	    private static final Set<String> GRADES = Set.of("A", "B", "C");
294	
295	    private final PersonRepository people;
296	    private final SheetService sheets;
297	    private final Audit audit;
298	
299	    public PersonService(PersonRepository people, SheetService sheets, Audit audit) {
300	        this.people = people;
301	        this.sheets = sheets;
302	        this.audit = audit;
303	    }
304	
305	    @Transactional(readOnly = true)
306	    public List<Person> list(String sheetId) {
307	        return people.findBySheetIdOrderByIdAsc(sheetId);
308	    }
309	
310	    @Transactional
311	    public Person add(String sheetId, String user, String name, String grade) {
312	        sheets.load(sheetId, user);
313	        String trimmed = name.trim();
314	        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
315	            throw nameInUse();
316	        }
317	        Person person = people.save(new Person(sheetId, trimmed, grade));
318	        audit.change("PERSON_ADDED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
319	        return person;
320	    }
321	
322	    /** A line of an import that breaks a rule: its number (from 1) and why. */
323	    public record ImportError(int line, String message) {
324	    }
325	
326	    /**
327	     * How many people an import added and how many existing ones it updated, or the lines that
328	     * stopped it (then nothing is changed).
329	     */
330	    public record ImportResult(int added, int updated, List<ImportError> errors) {
331	    }
332	
333	    /**
334	     * Import people from lines of name,grade. Every line is checked first with the rules of the form;
335	     * a name repeated in the paste is compared like uniqueness on the sheet. If any line breaks a
336	     * rule nothing is changed; otherwise, in order, a name already on the sheet has its grade
337	     * updated and any other name is added. Blank lines are skipped.
338	     */
339	    @Transactional
340	    public ImportResult importPeople(String sheetId, String user, String text) {
341	        String[] lines = text.split("\\r?\\n", -1);
342	        List<ImportError> errors = new ArrayList<>();
343	        List<String[]> rows = new ArrayList<>();
344	        Set<String> seen = new HashSet<>();
345	        for (int i = 0; i < lines.length; i++) {
346	            String line = lines[i];
347	            if (line.isBlank()) {
348	                continue;
349	            }
350	            int number = i + 1;
351	            int comma = line.lastIndexOf(',');
352	            String name = (comma < 0 ? line : line.substring(0, comma)).trim();
353	            String grade = comma < 0 ? "" : line.substring(comma + 1).trim();
354	            String error = null;
355	            if (name.isEmpty()) {
356	                error = "Enter a name.";
357	            } else if (name.length() > MAX_NAME) {
358	                error = "The name is too long.";
359	            } else if (!GRADES.contains(grade)) {
360	                error = "The grade must be A, B or C.";
361	            } else if (!seen.add(name.toLowerCase(Locale.ROOT))) {
362	                error = "That name is repeated in the import.";
363	            }
364	            if (error != null) {
365	                errors.add(new ImportError(number, error));
366	            } else {
367	                rows.add(new String[] {name, grade});
368	            }
369	        }
370	        if (!errors.isEmpty()) {
371	            return new ImportResult(0, 0, errors);
372	        }
373	        if (!rows.isEmpty()) {
374	            sheets.load(sheetId, user);
375	        }
376	        int added = 0;
377	        int updated = 0;
378	        for (String[] row : rows) {
379	            Optional<Person> existing = people.findFirstBySheetIdAndNameIgnoreCase(sheetId, row[0]);
380	            if (existing.isPresent()) {
381	                Person person = existing.get();
382	                person.setGrade(row[1]);
383	                person = people.saveAndFlush(person);
384	                audit.change("PERSON_EDITED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
385	                updated++;
386	            } else {
387	                Person person = people.save(new Person(sheetId, row[0], row[1]));
388	                audit.change("PERSON_ADDED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
389	                added++;
390	            }
391	        }
392	        return new ImportResult(added, updated, List.of());
393	    }
394	
395	    @Transactional
396	    public Person update(String sheetId, String user, Long personId, long version, String name, String grade) {
397	        Person person = people.findByIdAndSheetId(personId, sheetId)
398	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
399	        if (person.getVersion() != version) {
400	            throw changedMeanwhile();
401	        }
402	        String trimmed = name.trim();
403	        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, personId)) {
404	            throw nameInUse();
405	        }
406	        person.setName(trimmed);
407	        person.setGrade(grade);
408	        try {
409	            person = people.saveAndFlush(person);
410	        } catch (OptimisticLockingFailureException e) {
411	            throw changedMeanwhile();
412	        }
413	        audit.change("PERSON_EDITED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
414	        return person;
415	    }
416	
417	    /**
418	     * Retire a person from a date (the sheet's today when none is given). A person already retired is
419	     * refused (409); claims dated on or before the date stay allowed.
420	     */
421	    @Transactional
422	    public Person retire(String sheetId, String user, Long personId, LocalDate from) {
423	        // Lock the sheet, so a claim added at the same moment sees the retirement.
424	        sheets.lock(sheetId);
425	        Person person = people.findByIdAndSheetId(personId, sheetId)
426	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
427	        if (person.getRetiredFrom() != null) {
428	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Person already retired");
429	        }
430	        person.setRetiredFrom(from != null ? from : sheets.today(sheetId));
431	        person = people.saveAndFlush(person);
432	        audit.change("PERSON_RETIRED", sheetId, user, "name=" + person.getName(), "from=" + person.getRetiredFrom());
433	        return person;
434	    }
435	
436	    /**
437	     * Put a person on hold, or release them from it. Holding one already held, or releasing one not
438	     * held, is refused (409).
439	     */
440	    @Transactional
441	    public Person hold(String sheetId, String user, Long personId, boolean held) {
442	        // Lock the sheet, so a period closed at the same moment sees the hold.
443	        sheets.lock(sheetId);
444	        Person person = people.findByIdAndSheetId(personId, sheetId)
445	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
446	        if (person.isHeld() == held) {
447	            throw new ResponseStatusException(HttpStatus.CONFLICT,
448	                    held ? "Person already on hold" : "Person not on hold");
449	        }
450	        person.setHeld(held);
451	        person = people.saveAndFlush(person);
452	        audit.change(held ? "PERSON_HELD" : "PERSON_RELEASED", sheetId, user, "name=" + person.getName());
453	        return person;
454	    }
455	
456	    /**
457	     * Name another person on the same sheet as one of this person's patrons. Naming themselves is
458	     * refused (422), and so is naming someone already a patron (409).
459	     */
460	    @Transactional
461	    public Person addPatron(String sheetId, String user, Long personId, Long patronId) {
462	        sheets.lock(sheetId);
463	        Person person = people.findByIdAndSheetId(personId, sheetId)
464	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
465	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
466	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron"));
467	        if (patron.getId().equals(person.getId())) {
468	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "A person cannot be their own patron");
469	        }
470	        if (!person.getPatronIds().add(patron.getId())) {
471	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Already a patron");
472	        }
473	        person = people.saveAndFlush(person);
474	        audit.change("PATRON_ADDED", sheetId, user, "name=" + person.getName(), "patron=" + patron.getName());
475	        return person;
476	    }
477	
478	    private static ResponseStatusException changedMeanwhile() {
479	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Person changed since it was loaded");
480	    }
481	
482	    private static ResponseStatusException nameInUse() {
483	        return new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use");
484	    }
485	}
