507	/**
508	 * The claims kept on a sheet, newest first. A claim without a date takes the sheet's today; a
509	 * missing note is stored empty. Only a DRAFT claim can be edited (409); an open claim is changed by
510	 * voiding it and adding a new one. No claim dated in a closed period can be added, edited or change
511	 * status (423). No claim dated after its person's retirement date can be added or edited (422).
512	 */
513	@Service
514	public class ClaimService {
515	
516	    private final ClaimRepository claims;
517	    private final PersonRepository people;
518	    private final PeriodRepository periods;
519	    private final RateService rates;
520	    private final RoleService roles;
521	    private final SheetService sheets;
522	    private final Audit audit;
523	
524	    public ClaimService(ClaimRepository claims, PersonRepository people, PeriodRepository periods, RateService rates,
525	            RoleService roles, SheetService sheets, Audit audit) {
526	        this.roles = roles;
527	        this.claims = claims;
528	        this.people = people;
529	        this.periods = periods;
530	        this.rates = rates;
531	        this.sheets = sheets;
532	        this.audit = audit;
533	    }
534	
535	    @Transactional(readOnly = true)
536	    public List<Claim> list(String sheetId) {
537	        return claims.findBySheetIdOrderByIdDesc(sheetId);
538	    }
539	
540	    @Transactional
541	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note) {
542	        sheets.load(sheetId, user);
543	        // Lock the sheet, so a period closed at the same moment is seen.
544	        sheets.lock(sheetId);
545	        Person person = people.findByIdAndSheetId(personId, sheetId)
546	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
547	        LocalDate on = date != null ? date : sheets.today(sheetId);
548	        refuseIfClosed(sheetId, on);
549	        refuseIfRetired(person, on);
550	        Claim claim = claims.save(new Claim(sheetId, personId, scaled(amount), on, note != null ? note : ""));
551	        record("CLAIM_ADDED", user, person, claim);
552	        return claim;
553	    }
554	
555	    @Transactional
556	    public Claim update(String sheetId, String user, Long claimId, BigDecimal amount, LocalDate date, String note) {
557	        sheets.lock(sheetId);
558	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
559	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
560	        LocalDate on = date != null ? date : sheets.today(sheetId);
561	        if (claim.getStatus() != ClaimStatus.DRAFT) {
562	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot be edited");
563	        }
564	        refuseIfClosed(sheetId, claim.getDate());
565	        refuseIfClosed(sheetId, on);
566	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
567	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
568	        refuseIfRetired(person, on);
569	        claim.setAmount(scaled(amount));
570	        claim.setDate(on);
571	        claim.setNote(note != null ? note : "");
572	        record("CLAIM_EDITED", user, person, claim);
573	        return claim;
574	    }
575	
576	    /**
577	     * Move a claim to the next status; a change its status does not allow is refused (409). Opening
578	     * gives the claim the sheet's next number; a voided claim keeps it (the number is never given again).
579	     * Opening records who opened it; that user cannot settle it (403).
580	     * Settling fixes the claim's due at its person's grade's rate in force on the claim's date, raised to
581	     * the sheet's floor, with its late charge added if it is overdue; later floor and late percent changes
582	     * leave it as fixed. A clerk
583	     * can settle a claim only when that due is at or below the sheet's clerk limit, if it has one (403);
584	     * a claim with no due (no rate) is then refused too, as it cannot be shown to be within the limit.
585	     * A steward settles any claim.
586	     */
587	    @Transactional
588	    public Claim changeStatus(String sheetId, String user, Long claimId, ClaimStatus next) {
589	        // Lock the sheet before reading the claim, so claims opened at the same moment get different numbers
590	        // and a period closed at the same moment is seen.
591	        Sheet sheet = sheets.lock(sheetId)
592	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
593	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
594	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
595	        refuseIfClosed(sheetId, claim.getDate());
596	        if (!claim.getStatus().canBecome(next)) {
597	            throw new ResponseStatusException(HttpStatus.CONFLICT,
598	                    "A " + claim.getStatus() + " claim cannot become " + next);
599	        }
600	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
601	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
602	        }
603	        Long number = next == ClaimStatus.OPEN ? Long.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
604	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
605	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
606	        claim.setStatus(next);
607	        claim.setNumber(number);
608	        if (next == ClaimStatus.OPEN) {
609	            claim.setOpenedBy(user);
610	        }
611	        List<String> extra = new ArrayList<>();
612	        if (next == ClaimStatus.SETTLED) {
613	            BigDecimal due = sheet.withLateCharge(sheet.floored(rates.inForce(sheetId, person.getGrade(), claim.getDate())
614	                    .map(rate -> claim.getAmount().multiply(rate.getRate())
615	                            .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
616	                    .orElse(null)), claim.getDate());
617	            refuseIfOverClerkLimit(sheet, user, due);
618	            claim.setSettledDue(due);
619	            extra.add("due=" + (due == null ? "n/a" : due.toPlainString()));
620	        }
621	        record(switch (next) {
622	            case OPEN -> "CLAIM_OPENED";
623	            case SETTLED -> "CLAIM_SETTLED";
624	            case VOID -> "CLAIM_VOIDED";
625	            case DRAFT -> throw new IllegalStateException();
626	        }, user, person, claim, number, extra);
627	        return claim;
628	    }
629	
630	    /** Refuse (403) a clerk settling a claim whose due is above the sheet's clerk limit. */
631	    private void refuseIfOverClerkLimit(Sheet sheet, String user, BigDecimal due) {
632	        BigDecimal limit = sheet.getClerkLimit();
633	        if (limit == null || roles.of(sheet.getId(), user) != Role.CLERK) {
634	            return;
635	        }
636	        if (due == null || due.compareTo(limit) > 0) {
637	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
638	                    "A clerk cannot settle a claim with a due above " + limit.toPlainString());
639	        }
640	    }
641	
642	    /** Refuse (423) a change to a claim dated in a closed period. */
643	    private void refuseIfClosed(String sheetId, LocalDate date) {
644	        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
645	                .filter(period -> period.isClosed() && period.contains(date))
646	                .findFirst()
647	                .ifPresent(period -> {
648	                    throw new ResponseStatusException(HttpStatus.LOCKED, "The period " + period.getName() + " is closed");
649	                });
650	    }
651	
652	    /** Refuse (422) a claim dated after its person's retirement date. */
653	    private static void refuseIfRetired(Person person, LocalDate date) {
654	        if (person.retiredOn(date)) {
655	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
656	                    person.getName() + " is retired from " + person.getRetiredFrom());
657	        }
658	    }
659	
660	    private void record(String event, String user, Person person, Claim claim) {
661	        record(event, user, person, claim, claim.getNumber(), List.of());
662	    }
663	
664	    /**
665	     * Amounts are written with two decimals, as shown, and dates as yyyy-mm-dd. A claim with a number adds number=&lt;number&gt;; any extra fields follow it.
666	     */
667	    private void record(String event, String user, Person person, Claim claim, Long number, List<String> extra) {
668	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
669	                "amount=" + claim.getAmount().toPlainString(), "date=" + claim.getDate()));
670	        if (number != null) {
671	            fields.add("number=" + number);
672	        }
673	        fields.addAll(extra);
674	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
675	    }
676	
677	    private static BigDecimal scaled(BigDecimal amount) {
678	        return amount.setScale(2, RoundingMode.UNNECESSARY);
679	    }
680	}
