989	    @Transactional(readOnly = true)
990	    public Optional<Rate> inForce(String sheetId, String grade, LocalDate date) {
991	        return rates.findBySheetIdAndGrade(sheetId, grade).stream()
992	                .filter(rate -> rate.getFrom() == null || !rate.getFrom().isAfter(date))
993	                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())));
994	    }
