996	    @Transactional
997	    public Rate set(String sheetId, String user, String grade, LocalDate from, BigDecimal pct) {
998	        sheets.load(sheetId, user);
999	        BigDecimal scaled = pct.setScale(2, RoundingMode.UNNECESSARY);
1000	        Rate rate = rates.findBySheetIdAndGrade(sheetId, grade).stream()
1001	                .filter(r -> Objects.equals(r.getFrom(), from))
1002	                .findFirst().orElse(null);
1003	        if (rate == null) {
1004	            rate = rates.saveAndFlush(new Rate(sheetId, grade, from, scaled));
1005	        } else {
1006	            rate.setRate(scaled);
1007	        }
1008	        List<String> fields = new ArrayList<>(List.of("grade=" + rate.getGrade(), "rate=" + rate.getRate().toPlainString()));
1009	        if (from != null) {
1010	            fields.add("from=" + from);
