package net.officefloor.hq.app.person;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** People on a sheet. The signed-in user's name is sent in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    /** The version is the one an edit sends back, so a save made from an out-of-date copy is refused. */
    public record PersonView(Long id, String name, String grade, long version, LocalDate retiredFrom,
            boolean held, List<Long> patronIds) {
        static PersonView of(Person person) {
            return new PersonView(person.getId(), person.getName(), person.getGrade(), person.getVersion(),
                    person.getRetiredFrom(), person.isHeld(), person.getPatronIds().stream().sorted().toList());
        }
    }

    /** The name is stored trimmed; one that is empty or only spaces is refused. */
    public record PersonRequest(
            @NotBlank @Size(max = 100) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade) {
    }

    /** An edit carries the version of the person it was made from. */
    public record PersonUpdateRequest(
            @NotBlank @Size(max = 100) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            @NotNull Long version) {
    }

    /** Retire a person from a date; a missing date is the sheet's today. */
    public record RetireRequest(LocalDate from) {
    }

    /** Name another person on the sheet as a patron. */
    public record PatronRequest(@NotNull Long patronId) {
    }

    /** Lines of name,grade pasted into the import box. */
    public record ImportRequest(@NotNull @Size(max = 100_000) String text) {
    }

    private final PersonService service;

    public PersonController(PersonService service) {
        this.service = service;
    }

    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(PersonView::of).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PersonView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated PersonRequest request) {
        return PersonView.of(service.add(sheetId.trim(), user.trim(), request.name(), request.grade()));
    }

    @PutMapping("/{personId}")
    public PersonView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated PersonUpdateRequest request) {
        return PersonView.of(service.update(sheetId.trim(), user.trim(), personId, request.version(),
                request.name(), request.grade()));
    }

    @PostMapping("/{personId}/retire")
    public PersonView retire(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody RetireRequest request) {
        return PersonView.of(service.retire(sheetId.trim(), user.trim(), personId, request.from()));
    }

    @PostMapping("/{personId}/hold")
    public PersonView hold(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PersonView.of(service.hold(sheetId.trim(), user.trim(), personId, true));
    }

    @PostMapping("/{personId}/release")
    public PersonView release(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PersonView.of(service.hold(sheetId.trim(), user.trim(), personId, false));
    }

    @PostMapping("/{personId}/patrons")
    public PersonView addPatron(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated PatronRequest request) {
        return PersonView.of(service.addPatron(sheetId.trim(), user.trim(), personId, request.patronId()));
    }

    @PostMapping("/import")
    public PersonService.ImportResult importPeople(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated ImportRequest request) {
        return service.importPeople(sheetId.trim(), user.trim(), request.text());
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.FetchType;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.HashSet;
import java.util.Set;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet, with a name and a grade (A, B or C), who may be retired from a date
 * and may be put on hold. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "grade", nullable = false)
    private String grade;

    /** The date the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** Whether the person is on hold: while held, their open claims count in no live total. */
    @Column(name = "held", nullable = false)
    private boolean held;

    /** The ids of the other people on the sheet this person names as their patrons. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_patron", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "patron_id", nullable = false)
    private Set<Long> patronIds = new HashSet<>();

    /** Raised each time the person is saved. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getGrade() {
        return grade;
    }

    public void setGrade(String grade) {
        this.grade = grade;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Whether a claim dated on this date is refused: it is after the person's retirement date. */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date.isAfter(retiredFrom);
    }

    public boolean isHeld() {
        return held;
    }

    public void setHeld(boolean held) {
        this.held = held;
    }

    /** Whether a claim of this person in this status counts toward the totals: an open one not while held. */
    public boolean counts(ClaimStatus status) {
        return status.counts() && !(held && status == ClaimStatus.OPEN);
    }

    public Set<Long> getPatronIds() {
        return patronIds;
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PersonRepository extends JpaRepository<Person, Long> {

    List<Person> findBySheetIdOrderByIdAsc(String sheetId);

    Optional<Person> findByIdAndSheetId(Long id, String sheetId);

    Optional<Person> findFirstBySheetIdAndNameIgnoreCase(String sheetId, String name);

    boolean existsBySheetIdAndNameIgnoreCase(String sheetId, String name);

    boolean existsBySheetIdAndNameIgnoreCaseAndIdNot(String sheetId, String name, Long id);
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The people kept on a sheet, in the order they were added. A name is stored without surrounding
 * spaces and is unique on its sheet regardless of case. An edit is made from a version of the
 * person; once someone else has saved the person since, it is refused.
 */
@Service
public class PersonService {

    private static final int MAX_NAME = 100;
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;

    public PersonService(PersonRepository people, SheetService sheets, Audit audit) {
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade) {
        sheets.load(sheetId, user);
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
            throw nameInUse();
        }
        Person person = people.save(new Person(sheetId, trimmed, grade));
        audit.change("PERSON_ADDED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
        return person;
    }

    /** A line of an import that breaks a rule: its number (from 1) and why. */
    public record ImportError(int line, String message) {
    }

    /**
     * How many people an import added and how many existing ones it updated, or the lines that
     * stopped it (then nothing is changed).
     */
    public record ImportResult(int added, int updated, List<ImportError> errors) {
    }

    /**
     * Import people from lines of name,grade. Every line is checked first with the rules of the form;
     * a name repeated in the paste is compared like uniqueness on the sheet. If any line breaks a
     * rule nothing is changed; otherwise, in order, a name already on the sheet has its grade
     * updated and any other name is added. Blank lines are skipped.
     */
    @Transactional
    public ImportResult importPeople(String sheetId, String user, String text) {
        String[] lines = text.split("\\r?\\n", -1);
        List<ImportError> errors = new ArrayList<>();
        List<String[]> rows = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i];
            if (line.isBlank()) {
                continue;
            }
            int number = i + 1;
            int comma = line.lastIndexOf(',');
            String name = (comma < 0 ? line : line.substring(0, comma)).trim();
            String grade = comma < 0 ? "" : line.substring(comma + 1).trim();
            String error = null;
            if (name.isEmpty()) {
                error = "Enter a name.";
            } else if (name.length() > MAX_NAME) {
                error = "The name is too long.";
            } else if (!GRADES.contains(grade)) {
                error = "The grade must be A, B or C.";
            } else if (!seen.add(name.toLowerCase(Locale.ROOT))) {
                error = "That name is repeated in the import.";
            }
            if (error != null) {
                errors.add(new ImportError(number, error));
            } else {
                rows.add(new String[] {name, grade});
            }
        }
        if (!errors.isEmpty()) {
            return new ImportResult(0, 0, errors);
        }
        if (!rows.isEmpty()) {
            sheets.load(sheetId, user);
        }
        int added = 0;
        int updated = 0;
        for (String[] row : rows) {
            Optional<Person> existing = people.findFirstBySheetIdAndNameIgnoreCase(sheetId, row[0]);
            if (existing.isPresent()) {
                Person person = existing.get();
                person.setGrade(row[1]);
                person = people.saveAndFlush(person);
                audit.change("PERSON_EDITED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
                updated++;
            } else {
                Person person = people.save(new Person(sheetId, row[0], row[1]));
                audit.change("PERSON_ADDED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
                added++;
            }
        }
        return new ImportResult(added, updated, List.of());
    }

    @Transactional
    public Person update(String sheetId, String user, Long personId, long version, String name, String grade) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (person.getVersion() != version) {
            throw changedMeanwhile();
        }
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, personId)) {
            throw nameInUse();
        }
        person.setName(trimmed);
        person.setGrade(grade);
        try {
            person = people.saveAndFlush(person);
        } catch (OptimisticLockingFailureException e) {
            throw changedMeanwhile();
        }
        audit.change("PERSON_EDITED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
        return person;
    }

    /**
     * Retire a person from a date (the sheet's today when none is given). A person already retired is
     * refused (409); claims dated on or before the date stay allowed.
     */
    @Transactional
    public Person retire(String sheetId, String user, Long personId, LocalDate from) {
        // Lock the sheet, so a claim added at the same moment sees the retirement.
        sheets.lock(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (person.getRetiredFrom() != null) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Person already retired");
        }
        person.setRetiredFrom(from != null ? from : sheets.today(sheetId));
        person = people.saveAndFlush(person);
        audit.change("PERSON_RETIRED", sheetId, user, "name=" + person.getName(), "from=" + person.getRetiredFrom());
        return person;
    }

    /**
     * Put a person on hold, or release them from it. Holding one already held, or releasing one not
     * held, is refused (409).
     */
    @Transactional
    public Person hold(String sheetId, String user, Long personId, boolean held) {
        // Lock the sheet, so a period closed at the same moment sees the hold.
        sheets.lock(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (person.isHeld() == held) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    held ? "Person already on hold" : "Person not on hold");
        }
        person.setHeld(held);
        person = people.saveAndFlush(person);
        audit.change(held ? "PERSON_HELD" : "PERSON_RELEASED", sheetId, user, "name=" + person.getName());
        return person;
    }

    /**
     * Name another person on the same sheet as one of this person's patrons. Naming themselves is
     * refused (422), and so is naming someone already a patron (409).
     */
    @Transactional
    public Person addPatron(String sheetId, String user, Long personId, Long patronId) {
        sheets.lock(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron"));
        if (patron.getId().equals(person.getId())) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "A person cannot be their own patron");
        }
        if (!person.getPatronIds().add(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Already a patron");
        }
        person = people.saveAndFlush(person);
        audit.change("PATRON_ADDED", sheetId, user, "name=" + person.getName(), "patron=" + patron.getName());
        return person;
    }

    private static ResponseStatusException changedMeanwhile() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Person changed since it was loaded");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use");
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The claims kept on a sheet, newest first. A claim without a date takes the sheet's today; a
 * missing note is stored empty. Only a DRAFT claim can be edited (409); an open claim is changed by
 * voiding it and adding a new one. No claim dated in a closed period can be added, edited or change
 * status (423). No claim dated after its person's retirement date can be added or edited (422).
 */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final PeriodRepository periods;
    private final RateService rates;
    private final RoleService roles;
    private final SheetService sheets;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, PersonRepository people, PeriodRepository periods, RateService rates,
            RoleService roles, SheetService sheets, Audit audit) {
        this.roles = roles;
        this.claims = claims;
        this.people = people;
        this.periods = periods;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByIdDesc(sheetId);
    }

    @Transactional
    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note) {
        sheets.load(sheetId, user);
        // Lock the sheet, so a period closed at the same moment is seen.
        sheets.lock(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseIfClosed(sheetId, on);
        refuseIfRetired(person, on);
        Claim claim = claims.save(new Claim(sheetId, personId, scaled(amount), on, note != null ? note : ""));
        record("CLAIM_ADDED", user, person, claim);
        return claim;
    }

    @Transactional
    public Claim update(String sheetId, String user, Long claimId, BigDecimal amount, LocalDate date, String note) {
        sheets.lock(sheetId);
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        LocalDate on = date != null ? date : sheets.today(sheetId);
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot be edited");
        }
        refuseIfClosed(sheetId, claim.getDate());
        refuseIfClosed(sheetId, on);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        refuseIfRetired(person, on);
        claim.setAmount(scaled(amount));
        claim.setDate(on);
        claim.setNote(note != null ? note : "");
        record("CLAIM_EDITED", user, person, claim);
        return claim;
    }

    /**
     * Move a claim to the next status; a change its status does not allow is refused (409). Opening
     * gives the claim the sheet's next number; a voided claim keeps it (the number is never given again).
     * Opening records who opened it; that user cannot settle it (403).
     * Settling fixes the claim's due at its person's grade's rate in force on the claim's date, raised to
     * the sheet's floor, with its late charge added if it is overdue; later floor and late percent changes
     * leave it as fixed. A clerk
     * can settle a claim only when that due is at or below the sheet's clerk limit, if it has one (403);
     * a claim with no due (no rate) is then refused too, as it cannot be shown to be within the limit.
     * A steward settles any claim.
     */
    @Transactional
    public Claim changeStatus(String sheetId, String user, Long claimId, ClaimStatus next) {
        // Lock the sheet before reading the claim, so claims opened at the same moment get different numbers
        // and a period closed at the same moment is seen.
        Sheet sheet = sheets.lock(sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        refuseIfClosed(sheetId, claim.getDate());
        if (!claim.getStatus().canBecome(next)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next);
        }
        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
        }
        Long number = next == ClaimStatus.OPEN ? Long.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        claim.setStatus(next);
        claim.setNumber(number);
        if (next == ClaimStatus.OPEN) {
            claim.setOpenedBy(user);
        }
        List<String> extra = new ArrayList<>();
        if (next == ClaimStatus.SETTLED) {
            BigDecimal due = sheet.withLateCharge(sheet.floored(rates.inForce(sheetId, person.getGrade(), claim.getDate())
                    .map(rate -> claim.getAmount().multiply(rate.getRate())
                            .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
                    .orElse(null)), claim.getDate());
            refuseIfOverClerkLimit(sheet, user, due);
            claim.setSettledDue(due);
            extra.add("due=" + (due == null ? "n/a" : due.toPlainString()));
        }
        record(switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalStateException();
        }, user, person, claim, number, extra);
        return claim;
    }

    /** Refuse (403) a clerk settling a claim whose due is above the sheet's clerk limit. */
    private void refuseIfOverClerkLimit(Sheet sheet, String user, BigDecimal due) {
        BigDecimal limit = sheet.getClerkLimit();
        if (limit == null || roles.of(sheet.getId(), user) != Role.CLERK) {
            return;
        }
        if (due == null || due.compareTo(limit) > 0) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "A clerk cannot settle a claim with a due above " + limit.toPlainString());
        }
    }

    /** Refuse (423) a change to a claim dated in a closed period. */
    private void refuseIfClosed(String sheetId, LocalDate date) {
        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
                .filter(period -> period.isClosed() && period.contains(date))
                .findFirst()
                .ifPresent(period -> {
                    throw new ResponseStatusException(HttpStatus.LOCKED, "The period " + period.getName() + " is closed");
                });
    }

    /** Refuse (422) a claim dated after its person's retirement date. */
    private static void refuseIfRetired(Person person, LocalDate date) {
        if (person.retiredOn(date)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    person.getName() + " is retired from " + person.getRetiredFrom());
        }
    }

    private void record(String event, String user, Person person, Claim claim) {
        record(event, user, person, claim, claim.getNumber(), List.of());
    }

    /**
     * Amounts are written with two decimals, as shown, and dates as yyyy-mm-dd. A claim with a number adds number=&lt;number&gt;; any extra fields follow it.
     */
    private void record(String event, String user, Person person, Claim claim, Long number, List<String> extra) {
        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
                "amount=" + claim.getAmount().toPlainString(), "date=" + claim.getDate()));
        if (number != null) {
            fields.add("number=" + number);
        }
        fields.addAll(extra);
        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
    }

    private static BigDecimal scaled(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.UNNECESSARY);
    }
}
