131	/** DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID instead. */
132	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
133	
134	/** The status changes a claim can be asked for, as named in the store's API. */
135	export type ClaimAction = 'open' | 'settle' | 'void';
