137	/**
138	 * Whether the claim counts toward claimed, due-total and every total: an OPEN or SETTLED one, but
139	 * not an OPEN one while its person is on hold.
140	 */
141	export function counts(claim: Claim, person: { held: boolean }): boolean {
142	  return claim.status === 'SETTLED' || (claim.status === 'OPEN' && !person.held);
143	}
