145	/** Days since 1970-01-01 of a yyyy-mm-dd date (proleptic Gregorian), without reading any clock. */
146	function epochDay(date: string): number {
147	  const [y0, m, d] = date.split('-').map(Number);
148	  const y = m <= 2 ? y0 - 1 : y0;
149	  const era = Math.floor(y / 400);
150	  const yoe = y - era * 400;
151	  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
152	  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
153	  return era * 146097 + doe - 719468;
154	}
155	
156	/** The yyyy-mm-dd date of a count of days since 1970-01-01. */
157	function fromEpochDay(days: number): string {
158	  const z = days + 719468;
159	  const era = Math.floor(z / 146097);
160	  const doe = z - era * 146097;
161	  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
162	  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
163	  const mp = Math.floor((5 * doy + 2) / 153);
164	  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
165	  const m = mp < 10 ? mp + 3 : mp - 9;
166	  const y = yoe + era * 400 + (m <= 2 ? 1 : 0);
167	  return `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
168	}
169	
170	/** A claim's due-by (yyyy-mm-dd): its date plus the sheet's terms in days. */
171	export function dueBy(claim: Claim, terms: number): string {
172	  return fromEpochDay(epochDay(claim.date) + terms);
173	}
174	
175	/** Whether the claim is overdue: OPEN, with its due-by before the sheet's today. */
176	export function overdue(claim: Claim, terms: number, today: string): boolean {
177	  return claim.status === 'OPEN' && dueBy(claim, terms) < today;
178	}
179	
180	/** How many days the claim's due-by is before the sheet's today; 0 when it is not. */
181	export function daysOverdue(claim: Claim, terms: number, today: string): number {
182	  return Math.max(0, epochDay(today) - epochDay(claim.date) - terms);
183	}
