194	/** Whole cents of a valid amount, so sums are exact. */
195	export function toCents(amount: string): number {
196	  const [whole, frac = ''] = amount.split('.');
197	  return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
198	}
