212	  /** Re-read the store; until it answers no claims are shown, so none is shown out of date. */
213	  async reload(): Promise<void> {
214	    this.all.set([]);
215	    try {
216	      this.all.set(await firstValueFrom(this.http.get<Claim[]>(`${this.sheetUrl()}/claims`, { headers: this.headers() })));
217	    } catch {
218	      this.all.set([]);
219	    }
220	  }
