222	  async add(personId: number, fields: ClaimFields): Promise<void> {
223	    const added = await firstValueFrom(
224	      this.http.post<Claim>(`${this.sheetUrl()}/people/${personId}/claims`, this.body(fields), { headers: this.headers() }),
225	    );
226	    this.all.update((list) => [added, ...list]);
227	  }
228	
229	  /**
230	   * The quick-add bar: a DRAFT claim of the amount, dated the sheet's today, for the person of the
231	   * name; the store adds the person first (grade A) when the name is not on the sheet.
232	   */
233	  async quickAdd(name: string, amount: string): Promise<Claim> {
234	    const added = await firstValueFrom(
