236	    );
237	    this.all.update((list) => [added, ...list]);
238	    return added;
239	  }
240	
241	  async update(id: number, fields: ClaimFields): Promise<void> {
242	    const saved = await firstValueFrom(
243	      this.http.put<Claim>(`${this.sheetUrl()}/claims/${id}`, this.body(fields), { headers: this.headers() }),
244	    );
245	    this.all.update((list) => list.map((c) => (c.id === saved.id ? saved : c)));
246	  }
247	
248	  /** Move a claim to its next status; the store refuses a change its status does not allow. */
249	  async act(id: number, action: ClaimAction): Promise<void> {
250	    const saved = await firstValueFrom(
251	      this.http.post<Claim>(`${this.sheetUrl()}/claims/${id}/${action}`, null, { headers: this.headers() }),
252	    );
253	    this.all.update((list) => list.map((c) => (c.id === saved.id ? saved : c)));
254	  }
255	
256	  private body(fields: ClaimFields) {
257	    return { amount: fields.amount.trim(), date: fields.date || null, note: fields.note };
258	  }
259	
260	  private sheetUrl(): string {
261	    const id = this.session.sheetId();
262	    if (!id) throw new Error('no sheet loaded');
263	    return `/api/sheets/${encodeURIComponent(id)}`;
264	  }
265	
266	  private headers(): Record<string, string> {
267	    const user = this.session.user();
268	    if (!user) throw new Error('not signed in');
269	    return { 'X-User': user };
270	  }
271	}
