package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Clock;
import java.time.LocalDate;
import java.util.Objects;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Loads sheets by id; a sheet never loaded before is created empty. The real clock is read only
 * here, to start a new sheet's "today"; everything else uses {@link #today(String)}.
 */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Audit audit;
    private final Clock clock = Clock.systemDefaultZone();

    public SheetService(SheetRepository sheets, Audit audit) {
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> create(id, user));
    }

    /** The sheet's "today": the date every decision and default date in the sheet uses. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseGet(() -> LocalDate.now(clock));
    }

    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id, user);
        sheet.setToday(today);
        return sheet;
    }

    /**
     * Change the sheet's clerk limit (two decimals; null for no limit), floor (two decimals; null
     * leaves it as it is) terms (days; null leaves them as they are) and late percent (two
     * decimals; null leaves it as it is). Each change is recorded as
     * SETTING_CHANGED key=&lt;key&gt; value=&lt;value&gt;, clerk-limit first, then floor, then terms, then late-pct, the
     * clerk limit's value empty for no limit; setting a value it already has records nothing.
     */
    @Transactional
    public Sheet setSettings(String id, String user, BigDecimal limit, BigDecimal floor, Integer terms,
            BigDecimal latePct) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        BigDecimal scaled = limit == null ? null : limit.setScale(2, RoundingMode.UNNECESSARY);
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !person.counts(claim.getStatus()) || !period.contains(claim.getDate())) {
                continue;
            }
            BigDecimal due = switch (claim.getStatus()) {
                case SETTLED -> claim.getSettledDue();
                default -> sheet.withLateCharge(sheet.floored(rates.inForce(sheetId, person.getGrade(), claim.getDate())
                        .map(rate -> claim.getAmount().multiply(rate.getRate())
                                .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
                        .orElse(null)), claim.getDate());
            };
            if (due != null) {
                total = total.add(due);
            }
        }
        period.close(total);
        audit.change("PERIOD_CLOSED", sheetId, user, "period=" + period.getName(), "total=" + total.toPlainString());
  private saving = false;

  /**
   * Each period's due-total in cents, by period id: the due figures (as shown, each already rounded)
   * of the counted claims dated in it, skipping those that are n/a.
   */
  private readonly dueCents = computed(() => {
    const byId = new Map(this.people().map((p) => [p.id, p]));
    const out = new Map<number, number>();
    for (const c of this.claims.all()) {
      const person = byId.get(c.personId);
      const period = this.periods.on(c.date);
      if (person === undefined || period === undefined || !counts(c, person)) continue;
      const due = this.rates.dueOf(c, person.grade);
      if (due !== undefined) out.set(period.id, (out.get(period.id) ?? 0) + due);
    }
    return out;
  });

  constructor() {
    // Re-read the store each time the sheet is (re-)loaded.
})
export class PersonClaims {
  private readonly claims = inject(Claims);
  private readonly session = inject(Session);
  private readonly rates = inject(Rates);
  protected readonly periods = inject(Periods);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  readonly grade = input.required<Grade>();
  /** yyyy-mm-dd the person is retired from, or null; a claim dated after it is refused. */
  readonly retiredFrom = input<string | null>(null);

  protected readonly mine = computed(() => this.claims.all().filter((c) => c.personId === this.personId()));
  protected readonly amount = signal('');
  protected readonly date = linkedSignal(() => this.session.today() ?? '');
  protected readonly note = signal('');
  protected readonly editingId = signal<number | null>(null);
  /** Set while a submit awaits the store, so a second submit does not store a second claim. */
  private saving = false;
  protected readonly error = signal<string | null>(null);
  /** The error of the last action taken on a claim's row, if it was refused. */
  protected readonly rowError = signal<{ id: number; message: string } | null>(null);

  protected readonly actions: { action: ClaimAction; label: string }[] = [
    { action: 'open', label: 'Open' },
    { action: 'settle', label: 'Settle' },
    { action: 'void', label: 'Void' },
  ];

  /**
   * A settled claim's due as fixed when it was settled; any other claim's due at its person's grade's
   * rate in force on the claim's date. n/a when there was or is no such rate.
   */
  protected due(claim: Claim): string {
    const cents = this.rates.dueOf(claim, this.grade());
    return cents === undefined ? 'n/a' : formatCents(cents);
  }

  /** The claim's due-by: its date plus the sheet's terms. */
  protected dueBy(claim: Claim): string {

