            @NotBlank @Size(max = 100) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            @NotNull Long version) {
    }

    /** Retire a person from a date; a missing date is the sheet's today. */

